    birth_facility TEXT NOT NULL DEFAULT '',
    mother_name_before_first_marriage TEXT NOT NULL DEFAULT '',
    father_name TEXT NOT NULL DEFAULT '',
    is_deceased VARCHAR(5) NOT NULL DEFAULT '' CHECK (is_deceased IN ('yes', 'no', '')),
